// Optimistic update pattern - UI responds instantly
toggleForm: async (dex: number, form: FormType, pokedex: string) => {
  const state = get();

  // 1. Update local state immediately (optimistic)
  set((state) => ({
    pokemon: {
      ...state.pokemon,
      [pokedex]: {
        ...(state.pokemon[pokedex] || {}),
        [dex]: updatedStatus,
      },
    },
  }));

  // 2. Try to sync with server if online, queue if offline
  if (state.isOnline) {
    try {
      await api.post('/dextracker/update', { dex, form, pokedex });
    } catch (error) {
      queuePendingUpdate({ dex, form, pokedex }); // Retry later
    }
  } else {
    queuePendingUpdate({ dex, form, pokedex }); // Will sync on reconnect
  }
}

// OpenAI Moderation API integration
const moderateContent = async (text: string) => {
  try {
    // Tier 1: Free OpenAI Moderation API (~200ms, 95% accurate)
    const response = await openai.moderations.create({
      input: text,
      model: 'text-moderation-latest'
    });

    const result = response.results[0];

    if (result.flagged) {
      // Return specific category that was violated
      const categories = Object.entries(result.categories)
        .filter(([_, flagged]) => flagged)
        .map(([category]) => category);

      return {
        approved: false,
        reason: `Content flagged for: ${categories.join(', ')}`,
        categories
      };
    }

    // Tier 2: GPT-4o-mini for edge cases (context-aware)
    if (needsAdvancedCheck(text)) {
      return await gptModeration(text);
    }

    return { approved: true };
  } catch (error) {
    // Tier 3: Fallback to basic profanity filter
    return basicProfanityCheck(text);
  }
};

// PostgreSQL RPC function for atomic counter increment
const incrementCounter = async () => {
  try {
    // Call custom Postgres function with user/anonymous ID
    const params = {
      p_event_key: eventKey,
      p_pokemon_name: pokemonName,
      p_user_id: isLoggedIn && user ? user.id : null,
      p_anonymous_id: !isLoggedIn && anonymousId ? anonymousId : null
    };

    const { data, error } = await supabase.rpc('increment_counter', params);

    if (data?.success) {
      // Returns both global count and user contribution
      setGlobalCount(data.event_counter.current_count);
      setUserCount(data.user_contribution);
      setLastUpdated(data.event_counter.updated_at);
    }
  } catch (error) {
    console.error('Failed to increment counter:', error);
  }
};

// Protected route with auth guard
export default function ProtectedLayout() {
  const { user, isLoading } = useAuth();
  const router = useRouter();

  useEffect(() => {
    if (!isLoading && !user) {
      // Redirect to sign-in if not authenticated
      router.replace('/sign-in');
    }
  }, [user, isLoading]);

  if (isLoading) return <LoadingScreen />;
  if (!user) return null;

  return (
    <Stack>
      <Stack.Screen name="(drawer)" options={{ headerShown: false }} />
      <Stack.Screen name="social/(tabs)" options={{ headerShown: false }} />
    </Stack>
  );
}

